create or replace function t011_full_name(
  p_first  in varchar2,
  p_middle in varchar2,
  p_last   in varchar2
) return varchar2 is
  v_parts sys.odci_stringlist;
begin
  v_parts := sys.odci_stringlist();
  v_parts.extend(p_first);
  if p_middle is not null then
    v_parts.extend(p_middle);
  end if;
  v_parts.extend(p_last);
  return trim(v_parts.join(' '));
end t011_full_name;
/
